```rust
use pallas_addresses::{Address, Network, PaymentKeyHash, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart};
use pallas_crypto::hash::{Hash, Hasher};
use pallas_crypto::key::ed25519::SecretKey;
use pallas_wallet::PrivateKey;
use rand_core::OsRng;
use seedelf_core::address::wallet_contract;
use seedelf_core::assets::{Asset as CoreAsset, Assets};
use seedelf_core::build::{self, AddressPayment, Chain, Class, Histories, Origin, Payment, Purpose};
use seedelf_core::constants::get_config;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{Asset, InlineDatum, ProtocolParameters, UtxoResponse};
use serde_json::{Value, json};

const TOKEN_POLICY: &str = "c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0";
struct World { chain: Chain, owner: Register, wallet: Address, signer: Hash<28> }
fn world() -> World {
    let rows: Value = serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    let chain = Chain { params: ProtocolParameters::from_koios(&rows[0]).unwrap(), network_flag: true, config: get_config(1, true).unwrap() };
    let key = SecretKey::new(OsRng);
    World { wallet: wallet_contract(true, chain.config.contract.wallet_contract_hash), owner: Register::create(random_scalar()).unwrap(),
        signer: Hasher::<224>::hash(PrivateKey::from(key).public_key().as_ref()), chain }
}
fn owned(w: &World, n: u8, lovelace: u64, tokens: &[(&str, u64)]) -> UtxoResponse {
    let register = w.owner.clone().rerandomize().unwrap();
    UtxoResponse { tx_hash: hex::encode([n; 32]), tx_index: 0, address: w.wallet.to_bech32().unwrap(), value: lovelace.to_string(),
        payment_cred: hex::encode(w.chain.config.contract.wallet_contract_hash),
        inline_datum: Some(InlineDatum { bytes: hex::encode(register.to_vec().unwrap()),
            value: json!({"constructor": 0, "fields": [{"bytes": register.generator}, {"bytes": register.public_value}]}) }),
        asset_list: Some(tokens.iter().map(|(name, q)| Asset { decimals: 0, quantity: q.to_string(), policy_id: TOKEN_POLICY.to_string(),
            asset_name: hex::encode(name), fingerprint: String::new() }).collect()),
        ..Default::default() }
}
fn class(id: &str, origin: Origin) -> Class { Class { id: id.into(), origin } }
fn box_class(u: &UtxoResponse, origin: Origin) -> Class { class(&format!("box:{}", u.tx_hash), origin) }
fn received_class(u: &UtxoResponse) -> Class { class(&format!("received:{}", u.tx_hash), Origin::Received) }
fn tokens(items: &[(&str, u64)]) -> Assets {
    items.iter().fold(Assets::new(), |all, (name, q)| all.add(CoreAsset::new(TOKEN_POLICY.to_string(), hex::encode(name), *q).unwrap()).unwrap())
}
fn key_address() -> Address {
    ShelleyAddress::new(Network::Testnet, ShelleyPaymentPart::Key(PaymentKeyHash::new([7; 28])), ShelleyDelegationPart::Null).into()
}
#[derive(Debug, Clone, Copy)] enum Out { Send, Public, Fund }
impl Out {
    fn purpose(self) -> Purpose { match self { Out::Fund => Purpose::Fund { session: Some("session:7".into()) }, _ => Purpose::Pay } }
    fn outputs(self, lovelace: u64, sent: &Assets) -> (Vec<Payment>, Vec<AddressPayment>) {
        let to_key = |lovelace: u64, tokens: Assets| AddressPayment { to: key_address(), lovelace, tokens };
        match self {
            Out::Send => (vec![Payment { register: Register::create(random_scalar()).unwrap().rerandomize().unwrap(), lovelace, tokens: sent.clone() }], Vec::new()),
            Out::Public => (Vec::new(), vec![to_key(lovelace, sent.clone())]),
            Out::Fund => (Vec::new(), vec![to_key(lovelace - 5_000_000, Assets::new()), to_key(5_000_000, Assets::new())]),
        }
    }
}
fn pays(w: &World, inputs: &[UtxoResponse], out: Out, lovelace: u64, sent: &Assets) -> anyhow::Result<()> {
    let (seedelfs, pay) = out.outputs(lovelace, sent);
    if pay.is_empty() { build::transfer_from(&w.chain, inputs, &seedelfs, &w.owner, w.signer) }
    else { build::sweep_many_from(&w.chain, inputs, &pay, &w.owner, w.signer) }.and_then(|s| s.estimate()).map(|_| ())
}
fn picked(w: &World, known: &[(&UtxoResponse, Class)], out: Out, lovelace: u64, sent: &Assets) -> anyhow::Result<Vec<UtxoResponse>> {
    let available: Vec<UtxoResponse> = known.iter().map(|(u, _)| (*u).clone()).collect();
    let h = known.iter().fold(Histories::new(out.purpose()), |h, (u, c)| h.with(&u.tx_hash, u.tx_index, c.clone()));
    let (seedelfs, pay) = out.outputs(lovelace, sent);
    if pay.is_empty() { build::transfer_apart(&w.chain, &available, &h, &seedelfs, &w.owner, w.signer) }
    else { build::sweep_many_apart(&w.chain, &available, &h, &pay, &w.owner, w.signer) }.map(|s| s.inputs())
}
fn most_paid(mut lo: u64, mut hi: u64, pays: impl Fn(u64) -> bool) -> u64 {
    assert!(pays(lo) && !pays(hi), "{lo} pays, {hi} doesn't");
    while hi - lo > 1 { let mid = lo + (hi - lo) / 2; if pays(mid) { lo = mid } else { hi = mid } }
    lo
}
fn names(utxos: &[UtxoResponse], named: &[(&str, &UtxoResponse)]) -> Vec<String> {
    let mut v: Vec<String> = utxos.iter().map(|u| named.iter().find(|(_, n)| n.tx_hash == u.tx_hash && n.tx_index == u.tx_index)
        .map_or_else(|| format!("{}#{}", &u.tx_hash[..8], u.tx_index), |(name, _)| name.to_string())).collect();
    v.sort(); v
}

/// D: no token sent; M (Origin::Own) holds 20 token types, its least + 0.5 ₳; T a token pool's way back; A a plain way back of ADA
/// alone; just under the most M and A pay, M and T are short. C: 1 of a token B holds (10 ₳, 20 types, 10 of it): B and A pay, B and T short.
#[test]
fn a_token_box_whose_token_opens_a_second_change_output_stays_out_where_a_box_of_ada_alone_pays() {
    let w = world(); let p = &w.chain.params;
    let least0 = build::minimum_deposit(p, &Assets::new()).unwrap();
    let least1 = build::minimum_deposit(p, &tokens(&[("pooltoken", 1)])).unwrap();
    let bundle_names: Vec<String> = (0..20).map(|i| format!("m{i:02}")).collect();
    let bundle: Vec<(&str, u64)> = bundle_names.iter().map(|n| (n.as_str(), 1)).collect();
    let least20 = build::minimum_deposit(p, &tokens(&bundle)).unwrap();
    let mut with_pool = bundle.clone(); with_pool.push(("pooltoken", 1));
    let least21 = build::minimum_deposit(p, &tokens(&with_pool)).unwrap();
    println!("least: ADA alone {least0}, one token {least1} (+{}), 20 types {least20}, a 21st token +{}", least1 - least0, least21 - least20);
    let mut wrong = Vec::new(); let none = Assets::new();
    let m = owned(&w, 0x23, least20 + 500_000, &bundle);
    for (t_ada, a_ada, n) in [(6_500_000u64, 6_000_000u64, 0u8), (7_500_000, 6_600_000, 1)] {
        let t = owned(&w, 0x74 + n, t_ada, &[("pooltoken", 1)]); let a = owned(&w, 0x33 + n, a_ada, &[]);
        let t_adds = build::adds(p, &t).unwrap();
        println!("D: M {} ₳ (20 types), T {t_ada} + token: weighs in one {}, pays beside a change of 20 types {t_adds}; A {a_ada}",
            least20 + 500_000, (u128::try_from(t_adds).unwrap() + u128::from(least0)).min(u128::from(t_ada)));
        let named = [("M", &m), ("T", &t), ("A", &a)];
        let (ma, mt) = (vec![m.clone(), a.clone()], vec![m.clone(), t.clone()]);
        for out in [Out::Send, Out::Public, Out::Fund] {
            let lo = if matches!(out, Out::Fund) { 6_100_000 } else { 2_000_000 };
            let lovelace = most_paid(lo, 30_000_000, |l| pays(&w, &ma, out, l, &none).is_ok()) - 20_000;
            pays(&w, &ma, out, lovelace, &none).unwrap_or_else(|e| panic!("D {out:?}: M and A pay: {e}"));
            let e = pays(&w, &mt, out, lovelace, &none).unwrap_err(); assert!(build::is_short(&e), "D {out:?}: M and T: {e}");
            for (a_origin, t_origin) in [(Origin::Lovejoin, Origin::Lovejoin), (Origin::Lovejoin, Origin::Mixed), (Origin::Mixed, Origin::Lovejoin)] {
                let known: Vec<(&UtxoResponse, Class)> = vec![(&m, class("public:0", Origin::Own)), (&t, box_class(&t, t_origin)), (&a, box_class(&a, a_origin))];
                let line = format!("D (T {t_ada}, A {a_ada}): {out:?} of {lovelace}, A {a_origin:?}, T {t_origin:?}");
                match picked(&w, &known, out, lovelace, &none) {
                    Ok(s) if names(&s, &named) == ["A", "M"] => println!("{line}: spent [A, M]"),
                    Ok(s) => wrong.push(format!("{line}: spent {:?}, where M and A pay", names(&s, &named))),
                    Err(e) => wrong.push(format!("{line}: refused: {e}")),
                }
            }
