    fn select(w: &World, available: &[UtxoResponse], h: &Histories, pays: &Pays) -> (Result<ScriptSpend>, Tally, std::time::Duration) {
        let none = Assets::new;
        let outputs = match pays {
            Pays::Seedelf(l) => payment_outputs(&w.chain, &[Payment { register: w.owner.clone().rerandomize().unwrap(), lovelace: *l, tokens: none() }]),
            Pays::Funding(l) => address_outputs(&w.chain, &[
