/// The most `make` pays with exactly `inputs`, to 1,000 lovelace.
fn most_paid_by(w: &World, make: &dyn Fn(u64) -> Spend, inputs: &[&UtxoResponse]) -> u64 {
    let pays = |l: u64| Paying::new(w, &make(l)).verdict(inputs) == Verdict::Pays;
    let mut hi: u64 = inputs.iter().map(|u| lovelace_of(u)).sum();
    let mut lo = hi / 2;
    assert!(pays(lo) && !pays(hi));
    while hi - lo > 1_000 {
        let mid = lo + (hi - lo) / 2;
        if pays(mid) { lo = mid } else { hi = mid }
    }
    lo
}

/// T1, T2 of 6 ₳ + poolA beside 1-2 boxes of 5.9 ₳ (or 7.5 ₳ beside 7.4 ₳), maybe one of 4.71 ₳, maybe one other
/// UTxO, 18-25 payments of 10 ₳; amounts 0-0.09 ₳ under what the pair, the other money and as many payments as one
/// transaction spends beside them pay.
fn band_balance(w: &World, seed: u64, unknown: bool) -> (Balance, Vec<Spend>) {
    let mut rng = Rng(seed.wrapping_mul(0x9e37_79b9_7f4a_7c15) | 1);
    let mut n = u32::try_from(seed % 100_000).unwrap() * 64;
    let mut next = || { n += 1; n };
    let band = rng.below(2) as usize;
    let (pair, beside) = ([6_000_000, 7_500_000][band], [5_900_000, 7_400_000][band]);
    let kind = |rng: &mut Rng| match rng.below(100) {
        0..40 => Kind::Mixed, 40..75 => Kind::Plain, _ if unknown => Kind::Unknown, _ => Kind::Plain,
    };
    let mut boxes: Vec<(UtxoResponse, Kind)> = Vec::new();
    for _ in 0..2 { let k = kind(&mut rng); boxes.push((utxo(w, next(), pair, Some("poolA")), k)); }
    for _ in 0..1 + rng.below(2) { let k = kind(&mut rng); boxes.push((utxo(w, next(), beside, None), k)); }
    if rng.below(2) == 0 { let k = kind(&mut rng); boxes.push((utxo(w, next(), 4_710_000, None), k)); }
    for i in (1..boxes.len()).rev() { let j = rng.below(i as u64 + 1) as usize; boxes.swap(i, j); }
    let nb = boxes.len();
    let mut items = boxes;
    let distinct = rng.below(2) as usize;
    let mut kinds = vec![Kind::Own, Kind::Received, Kind::OwnSession, Kind::OtherSession];
    for _ in 0..distinct {
        let k = kinds.remove(rng.below(kinds.len() as u64) as usize);
        let lovelace = [1_500_000, 2_000_000, 3_000_000][rng.below(3) as usize];
        items.push((utxo(w, next(), lovelace, None), k));
    }
    let smalls = 18 + rng.below(8) as usize;
    for _ in 0..smalls { items.push((utxo(w, next(), 10 * ADA, None), Kind::Received)); }
    let balance = Balance { items, boxes: nb, distinct, smalls, small: 10 * ADA };
    let fit = (22 - 2 - distinct).min(smalls);
    let target: Vec<&UtxoResponse> = (0..nb)
        .filter(|&i| holds_tokens(&balance.items[i].0))
        .map(|i| &balance.items[i].0)
        .chain(balance.items[nb..nb + distinct + fit].iter().map(|(u, _)| u))
        .collect();
    let mut near = |make: &dyn Fn(u64) -> Spend| most_paid_by(w, make, &target) - rng.below(10) * (ADA / 100);
    let (send, public, fund) = (near(&Spend::Send), near(&Spend::Public), near(&Spend::Fund));
    (balance, vec![Spend::Send(send), Spend::Public(public), Spend::Fund(fund)])
}

/// Whether a set at `level` that pays holds two boxes of one token pool.
fn pair_pays_at(balance: &Balance, spend: &Spend, paying: &mut Paying, level: (usize, usize)) -> bool {
    let pool = |i: usize| balance.items[i].0.asset_list.iter().flatten().map(|a| a.asset_name.clone()).next();
    (0..(1u32 << balance.boxes))
        .filter(|&mask| {
            let b = boxes_in(mask, balance);
            let (bu, bn, _) = boxes_key(&b, balance);
            let pools: Vec<String> = b.iter().filter_map(|&i| pool(i)).collect();
            (bu, bn) == level && (1..pools.len()).any(|j| pools[..j].contains(&pools[j]))
        })
        .any(|mask| pays_beside(balance, spend, paying, mask))
}

