/// l7reference#3: the new selection against 1e1b0647's own (`old`), timed in the same run over the same balance and
/// reruns, real builder, no verdict cache (two values: a cache answers almost every set). At most three times as long.
#[test]
fn l7reference_3_parts_plan_within_three_times_1e1b0647s_own_time() {
    let w = world();
    let r = parts_against_old(&w, 100, 100, 400, 1_200 * ADA);
    println!("... one selection {:?} against 1e1b0647's {:?} ({:.2}x); {} reruns {:?} against {:?} ({:.2}x)",
        r.new_one, r.old_one, r.new_one.as_secs_f64() / r.old_one.as_secs_f64(), r.count,
        r.new_reruns, r.old_reruns, r.new_reruns.as_secs_f64() / r.old_reruns.as_secs_f64());
    assert!(r.new_one <= r.old_one * 3, "one selection took {:?}, 1e1b0647's {:?}", r.new_one, r.old_one);
    assert!(r.new_reruns <= r.old_reruns * 3, "the reruns took {:?}, 1e1b0647's {:?}", r.new_reruns, r.old_reruns);
}
struct AgainstOld { new_one: std::time::Duration, old_one: std::time::Duration,
    new_reruns: std::time::Duration, old_reruns: std::time::Duration, count: usize }
fn parts_against_old(w: &World, unknown: u32, plain: u32, received: u32, lovelace: u64) -> AgainstOld {
    // the balance exactly as parts_shape builds it (:1263-1282), then:
    let h = balance.histories(Purpose::Pay, true);
    let both = |utxos: &[UtxoResponse], lovelace: u64| {
        let spend = Spend::Send(lovelace);
        let paying = Paying::new(w, &spend);
        let started = std::time::Instant::now();
        let picked = paying.apart(utxos, &h);
        let new = started.elapsed();
        let (seedelfs, _) = spend.outputs(w);
        let started = std::time::Instant::now();
        let old_built = old::built(&w.chain.params, utxos, &h, &Purpose::Pay, spend.floor(&w.chain.params), |inputs| {
            let inputs: Vec<UtxoResponse> = inputs.iter().map(|u| (*u).clone()).collect();
            match build::transfer_from(&w.chain, &inputs, &seedelfs, &w.owner, w.signer).and_then(|s| s.estimate().map(|_| ())) {
                Ok(()) => Verdict::Pays,
                Err(e) if build::is_short(&e) => Verdict::Short,
                Err(_) => Verdict::Failed,
            }
        });
        let old = started.elapsed();
        assert!(picked.is_ok() || !old_built, "refused where 1e1b0647 built");
        (new, old, picked)
    };
    // the first selection (expect_err, is_too_many), then parts_shape's rerun loop (:1293-1309), with each
    // rerun's `new` and `old` summed separately and `count` incremented per rerun
}
