    /// Names the boxes among `spent`, and counts the rest.
    fn named(spent: &[UtxoResponse], names: &[(&UtxoResponse, &str)]) -> String {
        let mut seen: Vec<&str> = Vec::new();
        let mut others = 0;
        for s in spent {
            match names
                .iter()
                .find(|(n, _)| n.tx_hash == s.tx_hash && n.tx_index == s.tx_index)
            {
                Some((_, name)) => seen.push(*name),
                None => others += 1,
            }
        }
        format!("{} and {others} others, {} inputs", seen.join(", "), spent.len())
    }

    /// Chunk 51, round seven's last look (l7still#1): rule 2 inside the same-token margin, at the input limit. T1 and
    /// T2, two ways back of one token pool, 6 ₳ and the pool's token each, plain or mixed; A, a plain way back of 5.9 ₳,
    /// which weighs more than either; U, a way back of unknown making of 10 ₳; 20 payments received of 10 ₳. Just under
    /// the most T1, T2 and the 20 pay in 22 inputs, the most one transaction spends, A, T1 and the 20 are short: T1, T2
    /// and the 20 pay without a box of unknown making, so the merge takes none (rule 2).
    #[test]
    fn l7still_1_rule_two_holds_beside_two_ways_back_of_one_token_pool_at_the_input_limit() {
        let w = world();
        let a = owned(&w, 0x31, 0, 5_900_000, &[]);
        let t1 = owned(&w, 0x70, 0, 6_000_000, &[("pooltoken", 1)]);
        let t2 = owned(&w, 0x71, 0, 6_000_000, &[("pooltoken", 1)]);
        let u = owned(&w, 0x32, 0, 10_000_000, &[]);
        let payments: Vec<UtxoResponse> = (0..20u8)
            .map(|i| owned(&w, 0x50 + i, 0, 10_000_000, &[]))
            .collect();
        let names = [(&a, "A"), (&t1, "T1"), (&t2, "T2"), (&u, "U")];
        let both = with_first(&[&t1, &t2], &payments, 20);
        let mut wrong = Vec::new();
        for out in [Out::Send, Out::Public, Out::Fund] {
            let most = most_paid(150_000_000, 230_000_000, |l| {
                pays_out(&w, &both, out, l).is_ok()
            });
            let lovelace = most - 50_000;
            // The premises: T1, T2 and the 20 pay, no box of unknown making among them; A beside T1 and the 20 is
            // short, and all of A, T1, T2 and the 20 too many inputs; U, A and the 20 pay as well.
            pays_out(&w, &both, out, lovelace).expect("T1, T2 and the 20 pay");
            let e = pays_out(&w, &with_first(&[&a, &t1], &payments, 20), out, lovelace).unwrap_err();
            assert!(build::is_short(&e), "{out:?}: A, T1 and the 20: {e}");
            let e = pays_out(&w, &with_first(&[&a, &t1, &t2], &payments, 20), out, lovelace)
                .unwrap_err();
            assert!(build::is_too_many(&e), "{out:?}: all 23: {e}");
            pays_out(&w, &with_first(&[&u, &a], &payments, 20), out, lovelace)
                .expect("U, A and the 20 pay");
            for t_origin in [Origin::Lovejoin, Origin::Mixed] {
                let mut known: Vec<(&UtxoResponse, Class)> = vec![
                    (&a, box_class(&a, Origin::Lovejoin)),
                    (&t1, box_class(&t1, t_origin)),
                    (&t2, box_class(&t2, t_origin)),
                    (&u, unknown_class(&u)),
                ];
                known.extend(payments.iter().map(|p| (p, received_class(p))));
                let line = match picked_out(&w, &known, out, lovelace) {
                    Ok(spent) => {
                        let line = format!(
                            "{out:?} of {lovelace} (T1, T2 and the 20 pay up to {most}), T {t_origin:?}: spent {}",
                            named(&spent, &names)
                        );
                        println!("{line}");
                        if !outpoints(&spent).contains(&one(&u)[0]) {
                            continue;
                        }
                        line
                    }
                    Err(e) => format!("{out:?} of {lovelace}, T {t_origin:?}: refused: {e}"),
                };
                wrong.push(line);
            }
        }
        assert!(
            wrong.is_empty(),
            "a box of unknown making merged where T1, T2 and the 20 pay without one:\n{}",
            wrong.join("\n")
        );
    }

