        let known: Vec<(&UtxoResponse, Class)> = vec![
            (&o, class("public:0", Origin::Own)),
            (&a, box_class(&a, Origin::Lovejoin)),
            (&t1, box_class(&t1, Origin::Lovejoin)),
            (&t2, box_class(&t2, Origin::Lovejoin)),
        ];
        let names = [(&o, "O"), (&a, "A"), (&t1, "T1"), (&t2, "T2")];
        let both = vec![o.clone(), t1.clone(), t2.clone()];
        let mut wrong = Vec::new();
        for out in [Out::Send, Out::Public, Out::Fund] {
            let most = most_paid(6_000_000, 30_000_000, |l| pays_out(&w, &both, out, l).is_ok());
            let lovelace = most - 50_000;
            let e = pays_out(&w, &[o.clone(), a.clone(), t1.clone()], out, lovelace).unwrap_err();
            assert!(build::is_short(&e), "{out:?}: O, A and T1: {e}");
            let spent = picked_out(&w, &known, out, lovelace).unwrap();
            let line = format!(
                "{out:?} of {lovelace} (O, T1 and T2 pay up to {most}): spent {}",
                named(&spent, &names)
            );
            println!("{line}");
            if spent.len() > 3 {
                wrong.push(line);
            }
        }
        assert!(wrong.is_empty(), "three boxes merged where two pay:\n{}", wrong.join("\n"));
    }
